mapper.select:
SELECT s.id,u.id as userId,u.`name` as username, CASE WHEN s.semester='1' THEN '第一学期' ELSE '第二学期' END as semester, CASE WHEN u.gender='1' THEN '男' ELSE '女' END as genderName, d1.name as grade,d.name as classs, concat(d1.name, ' ', d.name) as gradeName, s.chinese,s.mathematics,s.english,s.general_science as generalScience, s.total_score,s.create_time as createTime from score s left join `user` u on u.id=s.user_id left join sys_dictionary d on d.id=s.classs left join sys_dictionary d1 on d1.id=s.grade
and u.name=#{score.username}
and s.user_id=#{score.userId}
and s.semester=#{score.semester}
and s.grade=#{score.grade}
and s.classs=#{score.classs}
order by s.create_time desc
